def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'
    if n == 1:
        return 'D'
    if n == 2:
        if history[0][1] == 'D' and history[1][1] == 'D':
            return 'D'
        return 'C'
    opp_defects = 0
    for h in history:
        if h[1] == 'D':
            opp_defects += 1
    if opp_defects == 0:
        return 'D'
    if history[-1][1] == 'D':
        if history[-2][1] == 'D':
            return 'D'
        return 'C'
    return 'C'
